var command = new LabCommand("R9", 3, "SetLevel", "D2", 75);
var events = new[] { new LabCompletion("R9", 2, "Completed"), new LabCompletion("R9", 3, "Completed") };
var requests = new Dictionary<(int Session, string Request), LabCommand> {
    [(command.Session, command.RequestId)] = command
};
foreach (var e in events)
{
    bool match = requests.TryGetValue((e.Session, e.RequestId), out var original);
    Console.WriteLine($"session={e.Session} matched={match}");
    if(match) Console.WriteLine($"target={original!.Target} value={original.Value}");
}
// 2 False；3 True，查回D2/75

long enteredMs=100, returnedMs=108, receivedMs=160, appliedMs=172, uiMs=225;
long synchronous=returnedMs-enteredMs;
long resultWait=receivedMs-returnedMs;
long controlQueue=appliedMs-receivedMs;
long uiQueue=uiMs-appliedMs;
long total=uiMs-enteredMs;
Console.WriteLine($"sync={synchronous} wait={resultWait} control={controlQueue} UI={uiQueue} total={total}");
Console.WriteLine(synchronous+resultWait+controlQueue+uiQueue==total); // True
